module firr27_v3 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire [7:0]  x,
    output reg  [15:0] y
);
    reg  [7:0]  xs [0:26];
    integer     i;
    reg  [31:0] acc;
    begin
        if (!rst_n) begin
            for (i = 0; i < 27; i = i + 1) xs[i] <= 8'd0;
